internal interface ISchemaIssuedScalar
{
    /// <summary>The plain atomic value.</summary>
    XdmValue Value { get; }
    /// <summary>The original governing type.</summary>
    object DeclaredType { get; }
    /// <summary>The actual atomic type.</summary>
    object ActualType { get; }
    /// <summary>The original assessment, or null for construction.</summary>
    object? OriginalAssessment { get; }
}

internal sealed class Evidence
{
    private readonly object _seal;
    internal Evidence(object seal, XdmValue value, object declared, object actual, object? origin, Snapshot? snapshot)
    { _seal = seal; Value = value; DeclaredType = declared; ActualType = actual; OriginalAssessment = origin; Snapshot = snapshot; }
    internal bool IsIssuedBy(object seal) => ReferenceEquals(_seal, seal);
    internal Snapshot? Snapshot { get; }
    internal XdmValue Value { get; }
    internal object DeclaredType { get; }
    internal object ActualType { get; }
    internal object? OriginalAssessment { get; }
}

    public static bool TryGetProvenance(in XdmValue value,out ISchemaAtomicProvenance? provenance)
    {
        provenance=null;
        if(!value.IsAtomic||XdmValue.SchemaTransportMarker(value) is not ISchemaAtomicObservation observation)return false;
        if(!observation.TryObserve(in value,out var observed)||observed is null)return false;
        provenance=observed;return true;
    }
}

private void CheckRaw(ISchemaIssuedScalar value)
{
    Check();
    if (!_advisor.OwnsTypedValue(value, _input, _origin)) throw new ArgumentException("Typed scalar is not issued for this exact input and origin.", nameof(value));
    Check();
}
private T ReadRaw<T>(ISchemaIssuedScalar value, Func<T> read)
{ CheckRaw(value); var result = read(); CheckRaw(value); return result; }

internal bool TryValidateTransport(XdmValue value, out SchemaEvidenceKernel.Evidence? evidence)
{
    evidence = null;
    if (XdmValue.SchemaTransportMarker(value) is not SchemaEvidenceKernel.Evidence marker || !ReferenceEquals(marker.Snapshot, _snapshot)) return false;
    Check(); ISchemaIssuedScalar scalar;
    lock (_gate) if (!_issued.TryGetValue(marker, out scalar!)) throw new ArgumentException("Unregistered scalar evidence.", nameof(value));
    CheckRaw(scalar); evidence = _kernel.ReadValue(value) ?? throw new ArgumentException("Missing scalar evidence.", nameof(value));
    CheckTypes(evidence); CheckRaw(scalar); return true;
}

private void CheckContainer()
{Check();if(!_issuer.OwnsContainer(_value,_originalInput,_snapshot.Input,_origin))throw new ArgumentException("Unissued typed container.");Check();}
private TResult Read<TSource,TResult>(TSource source,Func<TSource,TResult> getter)
{CheckContainer();var result=getter(source);CheckContainer();return result;}
private void OwnType(ISchemaComponentHandle? type)
{CheckContainer();if(type is null||!_authority.Owns(type))throw new ArgumentException("Unissued type component.");CheckContainer();}
private QueryTypedContainer.Cell Validate(SchemaAtomicItem item)
{
    CheckContainer();var evidence=item.TypeEvidence??throw new ArgumentException("Default atomic cell has no evidence.");
    var declared=Read(evidence,static e=>e.DeclaredType);OwnType(declared);
    var actual=Read(evidence,static e=>e.ActualType);OwnType(actual);
    var origin=Read(evidence,static e=>e.OriginalAssessment);
    if(!ReferenceEquals(origin,_origin))throw new ArgumentException("Atomic evidence has a different original assessment.");
    var value=item.Value;

private void ValidatePayload(XdmValue value)
{
    if(XdmValue.SchemaTransportMarker(value) is not null||value.Kind is < XdmValueKind.String or > XdmValueKind.Binary)throw new ArgumentException("Plain atomic payload required.");
    if(value.Kind==XdmValueKind.Integer)_=new XdmExactDecimal(value.BigIntegerValue,0,_digits,_scale);
    else if(value.Kind==XdmValueKind.Decimal){var(c,s)=value.DecimalRepresentation;_=new XdmExactDecimal(c,s,_digits,_scale);}
}
